# `specs/specs_scratch/gate_report.md`.
#
# Runtime: **CPU, High-RAM**. The RDKit work (scorer keys of ~1.5M SMILES, kNN labels, NP_Score) is checkpointed
# per chunk on Drive (`casmi_2026/_scratch_pool_ckpt/`): after a disconnect, **re-run all cells** and it resumes.
#
# | step | what |
# |---|---|
# | 1 | rows from v2-pool, COCONUT (R0's arrays), train, BIO, NP table |
# | 2 | scorer key (RDKit 2026.03.3 canonical tautomer InChIKey14), exact mass, fragments, charge per unique SMILES |
# | 3 | dedup on scorer key (train > v2 > COCONUT > BIO > NP table), flags OR'd; R1.1 superset check vs R0 |
# | 4 | NP labels: exact NP-table match, else kNN (Morgan r2 2048, Tanimoto ≥ 0.7); Ertl NP_Score |
# | 5 | write `casmi_2026/casmi26-scratch-pool/` + `MANIFEST.json` → upload as the private Kaggle dataset |
#
# Paste the final printout back into the chat.

# %%
import json, os, subprocess, sys, time
from pathlib import Path

from google.colab import drive
drive.mount("/content/drive")

ROOT = Path(os.environ.get("CASMI_INPUT", "/content/drive/MyDrive/casmi_2026"))
OUT = ROOT / "casmi26-scratch-pool"
CKPT = ROOT / "_scratch_pool_ckpt"
VERSION = "v1"
WORKERS = os.cpu_count() or 2
PKG_FILES = None  # @@PKG_FILES@@
PKG_ROOT = Path("/content/pkg")
for rel, src in PKG_FILES.items():
    p = PKG_ROOT / rel
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(src, encoding="utf-8")
sys.path.insert(0, str(PKG_ROOT))
for p in (OUT, CKPT):
    p.mkdir(parents=True, exist_ok=True)

# RDKit pinned to the scorer's version (an offline wheel only if it matches this Python, else PyPI)
RDKIT_PIN = "2026.03.3"
PY_TAG = f"cp{sys.version_info.major}{sys.version_info.minor}"
RDKIT_WHL = next(iter(sorted(ROOT.glob(f"*/rdkit-*-{PY_TAG}-*.whl"))), None)
cmd = ([sys.executable, "-m", "pip", "install", "-q", "--no-deps", str(RDKIT_WHL)] if RDKIT_WHL is not None
       else [sys.executable, "-m", "pip", "install", "-q", f"rdkit=={RDKIT_PIN}"])
r_ = subprocess.run(cmd, capture_output=True, text=True)
if r_.returncode != 0:
    raise RuntimeError("rdkit install failed:\n" + r_.stdout[-2000:] + "\n" + r_.stderr[-2000:])
import rdkit  # noqa: E402
assert rdkit.__version__ == RDKIT_PIN, rdkit.__version__
print("rdkit", rdkit.__version__, "| cpus", WORKERS)

from casmi_scratch import pool_build as PB  # noqa: E402


def find(name):
    for depth in ("*", "*/*", "*/*/*"):
        hits = sorted(ROOT.glob(f"{depth}/{name}"), key=lambda p: len(str(p)))
        hits = [h for h in hits if CKPT not in h.parents and OUT not in h.parents]
        if hits:
            return hits[0]
    raise FileNotFoundError(f"{name} not found under {ROOT} (is the dataset on Drive?)")


T0 = time.time()
TRAIN = find("train.parquet")
INPUTS = dict(train=TRAIN, v2=find("pool_meta.parquet"), coco=find("coco_meta.pkl").parent,
              bio=find("bio_meta.pkl").parent, np_table=find("natural_products.parquet"))
for k, v in INPUTS.items():
    print(f"  {k:9s} {v}")

# %% [markdown]
# ## Build (stages: 1 rows, 2 keys, 3 merge + R1.1, 4 labels + NP_Score, 5 write)

# %%
MANIFEST = PB.build({k: str(v) for k, v in INPUTS.items()}, str(OUT), str(CKPT), VERSION, workers=WORKERS)
print(json.dumps({k: MANIFEST[k] for k in ("version", "stats", "np_parity", "R1_1", "labels", "files")}, indent=1,
                 default=str))
print(f"Done in {time.time() - T0:.0f}s. Upload {OUT} as the private Kaggle dataset `casmi26-scratch-pool`, "
      f"then run casmi_scratch_r1_audit_colab.ipynb.")
